<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, RotateCw, Download, Paperclip, Trash2, ChevronRight } from 'lucide-vue-next'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ApiError, authorizedDownload, errorText } from '../api'
import { knowledge, unitStatus, versionStatus, displayTime, fileSize, grantSummary, type UnitDetail, type Version, type Grant, type GrantOptions, type Attachment } from '../knowledge'
import { useAuth } from '../stores/auth'
import { useUnsaved } from '../useUnsaved'
import PageHeader from '../components/PageHeader.vue'
import AsyncState from '../components/AsyncState.vue'
import KnowledgeGrantPicker from '../components/KnowledgeGrantPicker.vue'
import KnowledgeImage from '../components/KnowledgeImage.vue'
import KnowledgeBody from '../components/KnowledgeBody.vue'
const route=useRoute(),router=useRouter(),auth=useAuth(),id=computed(()=>String(route.params.id)),unit=ref<UnitDetail|null>(null),loading=ref(true),error=ref(''),busy=ref(false),actionError=ref('')
const tab=ref('content'),versions=ref<Version[]>([]),versionLoading=ref(false),versionError=ref(''),selectedVersion=ref<Version|null>(null),selectedLoading=ref(false),selectedError=ref('')
const grants=ref<Grant[]>([]),grantBaseline=ref('[]'),options=ref<GrantOptions>({departments:[],roles:[],users:[]}),optionsReady=ref(false),optionsError=ref(''),previewUser=ref(''),previewResult=ref<boolean|null>(null),previewBusy=ref(false),previewError=ref(''),fileInput=ref<HTMLInputElement|null>(null),attachmentBusy=ref(false)
const grantDirty=computed(()=>JSON.stringify(grants.value)!==grantBaseline.value)
const maintenance=computed(()=>unit.value?.is_maintenance_view??(unit.value?.creator_id===auth.user?.id&&['knowledge:create','knowledge:import','knowledge:update'].some(auth.has)))
const images=computed(()=>(unit.value?.attachments||[]).filter(file=>!!file.image_url))
const canEdit=computed(()=>!!unit.value?.can_edit&&auth.has('knowledge:update'))
const canVersions=computed(()=>!!unit.value?.can_manage_versions&&auth.has('knowledge:update'))
const canPermissions=computed(()=>!!unit.value?.can_manage_permissions&&auth.has('knowledge:permissions'))
useUnsaved(()=>grantDirty.value,()=>busy.value||attachmentBusy.value)
let accessGeneration=0,sequence=0,interval:ReturnType<typeof setInterval>,alive=true
function clear(){accessGeneration++;unit.value=null;versions.value=[];selectedVersion.value=null;grants.value=[];grantBaseline.value='[]';previewResult.value=null}
async function load(silent=false){const s=++sequence;if(!silent)loading.value=true;error.value='';try{const r=await knowledge.detail(id.value);if(s!==sequence||!alive)return;if(unit.value&&(unit.value.status!==r.status||JSON.stringify(unit.value.permission_summary)!==JSON.stringify(r.permission_summary)))previewResult.value=null;unit.value=r;if(!grantDirty.value||!r.can_manage_permissions){grants.value=r.grants||[];grantBaseline.value=JSON.stringify(grants.value)}if(!r.can_manage_versions){versions.value=[];selectedVersion.value=null;if(tab.value==='versions')tab.value='content'}if(!r.can_manage_permissions&&tab.value==='permissions')tab.value='content';if(tab.value==='versions'&&r.can_manage_versions)await loadVersions();if(canPermissions.value||auth.has('knowledge:preview')){if(!optionsReady.value)void loadOptions()}}catch(e){if(s===sequence){clear();error.value=errorText(e)}}finally{if(s===sequence)loading.value=false}}
async function loadVersions(){const generation=accessGeneration;versionLoading.value=true;versionError.value='';try{const result=await knowledge.versions(id.value);if(generation===accessGeneration&&alive)versions.value=result.items}catch(e){versions.value=[];versionError.value=errorText(e)}finally{versionLoading.value=false}}
async function loadOptions(){optionsError.value='';try{options.value=await knowledge.options();optionsReady.value=true}catch(e){options.value={departments:[],roles:[],users:[]};optionsError.value=errorText(e)}}
async function viewVersion(version:Version){const generation=accessGeneration;selectedLoading.value=true;selectedError.value='';selectedVersion.value=null;try{const result=await knowledge.version(id.value,version.id);if(generation===accessGeneration&&alive)selectedVersion.value=result}catch(e){selectedError.value=errorText(e)}finally{selectedLoading.value=false}}
async function run(action:()=>Promise<unknown>,message:string){if(busy.value)return;busy.value=true;actionError.value='';try{await action();ElMessage.success(message);await load(true)}catch(e){actionError.value=errorText(e);if(e instanceof ApiError&&[403,404].includes(e.status))await load(true)}finally{busy.value=false}}
async function changeStatus(status:string){const title=status==='published'?'发布知识':status==='disabled'?'停用知识':'撤销发布';const message=status==='published'?'当前已激活的版本将按访问范围向读者开放。':status==='disabled'?'停用后立即停止读者阅读、下载与检索。':'撤销后转为草稿，读者立即停止阅读、下载与检索。';try{await ElMessageBox.confirm(message,`${title}「${unit.value?.title}」`,{confirmButtonText:title,cancelButtonText:'取消'});await run(()=>knowledge.status(id.value,status),status==='published'?'知识已发布':status==='disabled'?'知识已停用':'已转为草稿')}catch{}}
async function activate(v:Version){try{await ElMessageBox.confirm(`将第 ${v.version_number} 版设为当前版本。${unit.value?.status==='published'?'读者将开始读取该版本。':'激活后仍需发布，读者才能访问。'}`,'激活此版本',{confirmButtonText:'确认激活',cancelButtonText:'取消'});await run(()=>knowledge.activate(id.value,v.id),'当前版本已切换')}catch{}}
async function rebuild(v:Version){await run(()=>knowledge.rebuild(id.value,v.id),'已创建重建任务，原发布版本继续可用');tab.value='versions';void loadVersions()}
async function saveGrants(){if(!canPermissions.value)return;await run(async()=>{await knowledge.permissions(id.value,grants.value);grantBaseline.value=JSON.stringify(grants.value);previewResult.value=null},'访问范围已保存')}
async function preview(){if(!previewUser.value)return;previewBusy.value=true;previewError.value='';previewResult.value=null;try{const r=await knowledge.preview(id.value,previewUser.value);previewResult.value=r.authorized_unit_ids.includes(id.value)}catch(e){previewError.value=errorText(e)}finally{previewBusy.value=false}}
async function uploadAttachment(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;attachmentBusy.value=true;actionError.value='';try{await knowledge.attach(id.value,file,unit.value?.latest_version?.id);ElMessage.success('附件已上传');await load(true)}catch(e){actionError.value=errorText(e)}finally{attachmentBusy.value=false;input.value=''}}
async function download(file:Attachment){actionError.value='';try{await authorizedDownload(`/knowledge/files/${file.id}/download`,file.file_name)}catch(e){actionError.value=errorText(e);if(e instanceof ApiError&&[403,404].includes(e.status))await load(true)}}
async function removeAttachment(file:Attachment){try{await ElMessageBox.confirm(`删除附件「${file.file_name}」后不可再下载。`,'删除附件',{confirmButtonText:'确认删除',cancelButtonText:'取消'});await run(()=>knowledge.detach(id.value,file.id),'附件已删除')}catch{}}
async function remove(){try{await ElMessageBox.confirm(`删除「${unit.value?.title}」后立即停止阅读、下载与检索。`,'删除知识',{confirmButtonText:'确认删除',cancelButtonText:'取消'});busy.value=true;await knowledge.remove([id.value]);grantBaseline.value=JSON.stringify(grants.value);ElMessage.success('知识已删除');busy.value=false;await router.push('/knowledge')}catch(e){if(e!=='cancel'&&e!=='close')actionError.value=errorText(e)}finally{busy.value=false}}
function refresh(){if(document.visibilityState==='visible')void load(true)}
watch(tab,v=>{if(v==='versions'&&canVersions.value)void loadVersions()})
watch(previewUser,()=>{previewResult.value=null;previewError.value=''})
watch(()=>auth.permissions.join('|'),()=>{clear();void load()})
onMounted(()=>{void load();interval=setInterval(refresh,15000);window.addEventListener('focus',refresh)})
onUnmounted(()=>{alive=false;accessGeneration++;sequence++;clearInterval(interval);window.removeEventListener('focus',refresh)})
</script>
<template>
 <div class="knowledge-screen">
 <RouterLink to="/knowledge" class="text-button back-link"><ArrowLeft :size="16"/>返回知识列表</RouterLink>
 <PageHeader title="知识详情" :description="unit?.category?`${unit.category} · ${unit.creator_name||'—'} 创建`:undefined"><button class="icon-button" aria-label="刷新知识详情" :disabled="loading||busy" @click="load()"><RotateCw :size="16"/></button><RouterLink v-if="canEdit" :to="`/knowledge/${id}/edit`" class="button primary">编辑知识</RouterLink></PageHeader>
 <AsyncState :loading="loading" :error="error" @retry="load">
 <template v-if="unit">
  <div class="knowledge-object-heading"><p class="document-title">{{unit.title}}</p><span class="status" :class="{active:unit.status==='published'}"><span></span>{{unitStatus[unit.status]||unit.status}}</span></div>
  <div class="version-strip"><div><span class="muted">当前发布</span><strong>{{unit.status==='published'&&unit.active_version?`第 ${unit.active_version.version_number} 版`:'尚未发布'}}</strong></div><ChevronRight v-if="canVersions" :size="16"/><div v-if="canVersions"><span class="muted">已激活版本</span><strong>{{unit.active_version?`第 ${unit.active_version.version_number} 版`:'未激活'}}</strong></div><div v-if="canVersions" class="version-latest"><span class="muted">最新版本</span><strong>{{unit.latest_version?`第 ${unit.latest_version.version_number} 版 · ${versionStatus[unit.latest_version.status]||unit.latest_version.status}`:'尚无版本'}}</strong></div><RouterLink v-if="(unit.batch_id||unit.latest_version?.batch_id)&&auth.has('knowledge:task:read')" :to="`/knowledge/import?batch=${unit.batch_id||unit.latest_version?.batch_id}`" class="text-button">查看构建进度</RouterLink></div>
  <div class="tabs" aria-label="知识详情内容"><button :class="{active:tab==='content'}" @click="tab='content'">正文</button><button :class="{active:tab==='attachments'}" @click="tab='attachments'">附件 <span class="num">{{unit.attachments?.length||0}}</span></button><button v-if="canVersions" :class="{active:tab==='versions'}" @click="tab='versions'">版本历史</button><button v-if="canPermissions||auth.has('knowledge:preview')" :class="{active:tab==='permissions'}" @click="tab='permissions'">访问范围</button></div>
  <p v-if="actionError" class="form-error" role="alert">{{actionError}}</p>
  <div v-if="tab==='content'" class="knowledge-detail-grid">
   <section class="document-main"><h2>{{maintenance?'最新版本正文':'当前发布正文'}}</h2><p v-if="maintenance" class="muted document-context">{{unit.latest_version?.id===unit.active_version_id?'与已激活版本一致。':'本页展示维护中的最新内容，尚未替换当前已激活版本。'}}</p><p v-if="unit.summary" class="document-summary">{{unit.summary}}</p><KnowledgeBody :content="unit.content||'正文正在解析，请在版本就绪后刷新。'" :files="unit.attachments||[]" :allow-images="auth.has('knowledge:file:read')" @unavailable="load(true)"/></section>
   <aside class="knowledge-facts"><h2>文档资料</h2><dl><dt>分类</dt><dd>{{unit.category||'未分类'}}</dd><dt>标签</dt><dd><div class="role-tags"><span v-for="tag in unit.tags" :key="tag" class="tag">{{tag}}</span><span v-if="!unit.tags?.length" class="muted">—</span></div></dd><dt>创建者</dt><dd>{{unit.creator_name||'—'}}</dd><dt>更新时间</dt><dd class="num">{{displayTime(unit.updated_at)}}</dd><dt>访问范围</dt><dd>{{grantSummary(unit.permission_summary)}}</dd></dl><div v-if="canEdit" class="publication-actions"><h3>发布管理</h3><button v-if="unit.status!=='published'" class="button" :disabled="busy||!unit.active_version_id" @click="changeStatus('published')">发布知识</button><p v-if="!unit.active_version_id" class="muted">先在版本历史中激活已就绪版本。</p><button v-if="unit.status==='published'" class="button" :disabled="busy" @click="changeStatus('draft')">撤销发布</button><button v-if="unit.status!=='disabled'" class="text-button" :disabled="busy" @click="changeStatus('disabled')">停用知识</button><button v-if="unit.status==='disabled'" class="text-button" :disabled="busy" @click="changeStatus('draft')">恢复为草稿</button></div><details class="trace-details"><summary>文档标识</summary><p>知识单元</p><span class="trace-id">{{unit.id}}</span><template v-if="unit.latest_version"><p>最新版本</p><span class="trace-id">{{unit.latest_version.id}}</span></template></details><button v-if="unit.can_delete&&auth.has('knowledge:delete')" class="text-button danger-text delete-unit" :disabled="busy" @click="remove"><Trash2 :size="15"/>删除知识</button></aside>
  </div>
  <section v-if="tab==='attachments'" class="detail-section"><div class="section-heading"><div><h2>文档附件</h2><p class="muted">{{canEdit?'新附件绑定最新版本；读者仅能下载当前发布版本的文件。':'仅显示当前发布版本可下载的文件。'}}</p></div><button v-if="unit.can_attach&&auth.has('knowledge:update')" class="button" :disabled="attachmentBusy||busy" @click="fileInput?.click()"><Paperclip :size="16"/>{{attachmentBusy?'上传中…':'上传附件'}}</button><input ref="fileInput" type="file" class="sr-only" tabindex="-1" aria-label="选择附件" @change="uploadAttachment"/></div><div v-if="!unit.attachments?.length" class="empty-state">这篇知识暂无附件。</div><ul v-else class="attachment-list"><li v-for="file in unit.attachments" :key="file.id"><div><strong>{{file.file_name}}</strong><p class="muted">{{fileSize(file.file_size)}} · {{file.purpose==='source'?'原始文档':'附件'}} <span v-if="canVersions">· {{file.version_id===unit.active_version_id?'当前版本':'其他版本'}}</span></p></div><div class="attachment-actions"><button v-if="auth.has('knowledge:file:read')" class="text-button" @click="download(file)"><Download :size="15"/>下载</button><button v-if="unit.can_attach&&auth.has('knowledge:update')&&file.purpose==='attachment'" class="icon-button" :aria-label="`删除附件 ${file.file_name}`" :disabled="busy" @click="removeAttachment(file)"><Trash2 :size="15"/></button></div></li></ul><div v-if="images.length&&auth.has('knowledge:file:read')" class="knowledge-images"><KnowledgeImage v-for="file in images" :key="file.id" :file-id="file.id" :name="file.file_name" @unavailable="load(true)"/></div></section>
  <section v-if="tab==='versions'&&canVersions" class="detail-section"><div class="section-heading"><div><h2>版本历史</h2><p class="muted">新版本构建成功后才可激活，构建失败不会替换原有可用版本。</p></div><button class="text-button" :disabled="versionLoading" @click="loadVersions">刷新版本</button></div><AsyncState :loading="versionLoading" :error="versionError" :empty="!versions.length" empty-text="尚无版本" @retry="loadVersions"><ul class="version-list"><li v-for="v in versions" :key="v.id"><div><strong>第 {{v.version_number}} 版</strong><span v-if="v.is_active" class="tag">当前版本</span><p class="muted">{{versionStatus[v.status]||v.status}} · {{displayTime(v.created_at)}}</p></div><div class="version-actions"><button class="text-button" :disabled="selectedLoading" @click="viewVersion(v)">查看内容</button><button v-if="v.status==='ready'&&!v.is_active" class="button" :disabled="busy" @click="activate(v)">激活</button><button class="text-button" :disabled="busy||['pending','processing','building'].includes(v.status)" @click="rebuild(v)">重建</button></div></li></ul></AsyncState><p v-if="selectedLoading" class="notice" role="status">正在读取版本内容…</p><p v-if="selectedError" class="form-error" role="alert">{{selectedError}}</p><div v-if="selectedVersion" class="version-content"><div class="section-heading"><h3>第 {{selectedVersion.version_number}} 版正文</h3><button class="text-button" @click="selectedVersion=null">收起</button></div><KnowledgeBody :content="selectedVersion.content||'此版本尚无正文。'" :files="selectedVersion.attachments||[]" :allow-images="auth.has('knowledge:file:read')" @unavailable="load(true)"/><details class="trace-details"><summary>版本与切片溯源 · {{selectedVersion.chunks?.length||0}} 个切片</summary><p class="trace-id">版本 {{selectedVersion.id}}</p><ol v-if="selectedVersion.chunks?.length" class="chunk-list"><li v-for="(chunk,index) in selectedVersion.chunks" :key="chunk.chunk_id||chunk.id"><strong>位置 {{chunk.chunk_index??index}}</strong><span class="trace-id">{{chunk.chunk_id||chunk.id}}</span><p v-if="chunk.position" class="muted">{{typeof chunk.position==='object'?Object.entries(chunk.position).map(([key,value])=>`${key}: ${value}`).join(' · '):chunk.position}}</p><p>{{chunk.content||''}}</p></li></ol></details><div v-if="selectedVersion.attachments?.length&&auth.has('knowledge:file:read')" class="version-attachments"><h3>此版本附件</h3><button v-for="file in selectedVersion.attachments" :key="file.id" class="text-button" @click="download(file)"><Download :size="15"/>{{file.file_name}}</button></div></div></section>
  <section v-if="tab==='permissions'&&(canPermissions||auth.has('knowledge:preview'))" class="detail-section permission-detail-grid"><div v-if="canPermissions"><h2>访问范围</h2><p v-if="optionsError" class="form-error" role="alert">{{optionsError}} <button class="text-button" @click="loadOptions">重试</button></p><KnowledgeGrantPicker v-if="optionsReady" v-model="grants" :options="options" :disabled="busy"/><div class="grant-save"><span class="muted">{{grantDirty?'有未保存的访问范围修改':'访问范围已保存'}}</span><button class="button primary" :disabled="busy||!grantDirty||!optionsReady" @click="saveGrants">{{busy?'保存中…':'保存访问范围'}}</button></div></div><aside v-if="auth.has('knowledge:preview')" class="permission-preview"><h2>授权预览</h2><p class="muted">检查指定成员现在能否阅读此文档，依据已保存的范围与当前发布状态。</p><label for="preview-user">预览成员</label><select id="preview-user" v-model="previewUser" :disabled="!optionsReady||previewBusy"><option value="">请选择成员</option><option v-for="person in options.users" :key="person.id" :value="person.id">{{person.display_name}} · {{person.username}}</option></select><button class="button" :disabled="!previewUser||previewBusy||grantDirty" @click="preview">{{previewBusy?'检查中…':'检查当前授权'}}</button><p v-if="grantDirty" class="muted">保存访问范围后可预览。</p><p v-if="previewError" class="form-error" role="alert">{{previewError}}</p><p v-if="previewResult!==null" class="preview-result" role="status">{{previewResult?'当前允许阅读':'当前不允许阅读'}}<small>{{previewResult?'已匹配授权且文档处于可读发布状态。':'请检查成员授权、账号状态以及文档是否已发布。'}}</small></p></aside></section>
 </template>
 </AsyncState>
 </div>
</template>
